import React, { useState, useEffect } from 'react';
import {
  Box,
  Paper,
  Typography,
  TextField,
  Button,
  Grid,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Divider,
  Alert,
  Snackbar,
  Container,
  FormControlLabel,
  Switch
} from '@mui/material';
import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import axios from 'axios';

const defaultInfraParams = {
  cloud_infra: {
    nat_gateway: 32.0,
    vpc_endpoints: 100.0,
    transit_gateway: 73.0,
    route53: 15.0
  },
  infra_management: {
    terraform_s3: 3.0,
    terraform_dynamodb: 2.0,
    cicd_pipeline: 51.0,
    multi_region_deployment: 222.0
  },
  security: {
    security_hub: 80.0,
    waf: 6.0,
    shield_advanced: 3000.0,
    guard_duty: 100.0,
    secrets_manager: 40.0,
    certificate_management: 33.0,
    access_management: 10.0
  },
  monitoring: {
    cloudwatch_metrics: 200.0,
    cloudwatch_logs: 300.0,
    cloudwatch_alarms: 50.0,
    systems_manager: 30.0,
    xray: 50.0,
    managed_prometheus: 200.0,
    grafana: 90.0,
    opensearch: 200.0
  },
  load_balancing: {
    api_gateway_per_million: 100.0,
    load_balancer_base: 200.0
  },
  caching: {
    elasticache_redis: 300.0,
    dynamodb_accelerator: 200.0
  },
  container: {
    ecr_helm_storage: 30.0,
    chart_museum: 100.0
  }
};

function PricingConfig() {
  const [pricingData, setPricingData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [notification, setNotification] = useState({ open: false, message: '', severity: 'success' });
  const [selectedProvider, setSelectedProvider] = useState('aws');
  const [selectedCategory, setSelectedCategory] = useState('network');
  const [scaleParams, setScaleParams] = useState({
    num_tenants: 500,
    consumers_per_tenant: 3,
    endpoints_per_tenant: 10000
  });
  const [loadParams, setLoadParams] = useState({
    messages_per_day: 100010,
    api_requests_per_day: 189,
    has_load: true,
    messages_per_endpoint: 10
  });
  const [infraParams, setInfraParams] = useState(defaultInfraParams);
  const [expanded, setExpanded] = useState('scale');
  const [costBreakdown, setCostBreakdown] = useState(null);

  useEffect(() => {
    fetchPricingData();
  }, []);

  const fetchPricingData = async () => {
    try {
      setLoading(true);
      const response = await axios.get('http://localhost:8000/pricing');
      setPricingData(response.data);
    } catch (error) {
      console.error('Error fetching pricing data:', error);
      setNotification({
        open: true,
        message: 'Failed to load pricing data',
        severity: 'error',
      });
    } finally {
      setLoading(false);
    }
  };

  const handleSavePricing = async () => {
    try {
      setSaving(true);
      await axios.post('http://localhost:8000/pricing', { pricing_data: pricingData });
      setNotification({
        open: true,
        message: 'Pricing data updated successfully',
        severity: 'success',
      });
    } catch (error) {
      console.error('Error saving pricing data:', error);
      setNotification({
        open: true,
        message: 'Failed to update pricing data',
        severity: 'error',
      });
    } finally {
      setSaving(false);
    }
  };

  const handlePricingChange = (provider, category, subcategory, key, value) => {
    setPricingData((prev) => {
      const newData = { ...prev };

      if (subcategory) {
        newData[provider][category][subcategory][key] = parseFloat(value);
      } else {
        newData[provider][category][key] = parseFloat(value);
      }

      return newData;
    });
  };

  const handleCloseNotification = () => {
    setNotification({ ...notification, open: false });
  };

  const handleAccordionChange = (panel) => (event, isExpanded) => {
    setExpanded(isExpanded ? panel : false);
  };

  const handleInfraParamChange = (category, param) => (event) => {
    setInfraParams(prev => ({
      ...prev,
      [category]: {
        ...prev[category],
        [param]: parseFloat(event.target.value) || 0
      }
    }));
  };

  const handleScaleParamChange = (param) => (event) => {
    setScaleParams(prev => ({
      ...prev,
      [param]: parseInt(event.target.value) || 0
    }));
  };

  const handleLoadParamChange = (param) => (event) => {
    const value = param === 'has_load' ? event.target.checked : (parseInt(event.target.value) || 0);
    setLoadParams(prev => ({
      ...prev,
      [param]: value
    }));
  };

  const calculateCosts = async () => {
    try {
      const response = await axios.post('http://localhost:8000/calculate-cost', {
        scale_params: scaleParams,
        load_params: loadParams,
        infra_params: infraParams
      });
      setCostBreakdown(response.data);
      setNotification({
        open: true,
        message: 'Cost calculation successful!',
        severity: 'success'
      });
    } catch (error) {
      setNotification({
        open: true,
        message: 'Error calculating costs: ' + error.message,
        severity: 'error'
      });
    }
  };

  if (loading) {
    return <Typography>Loading pricing data...</Typography>;
  }

  if (!pricingData) {
    return <Typography>No pricing data available</Typography>;
  }

  const renderNetworkPricing = () => {
    const networkData = pricingData[selectedProvider].network;

    return (
      <Grid container spacing={2}>
        {Object.entries(networkData).map(([size, costs]) => (
          <Grid item xs={12} key={size}>
            <Typography variant="subtitle1" gutterBottom>
              {size} Deployment
            </Typography>
            <Grid container spacing={2}>
              <Grid item xs={6}>
                <TextField
                  fullWidth
                  label="Data Transfer ($/GB)"
                  type="number"
                  value={costs.data_transfer}
                  onChange={(e) => handlePricingChange(selectedProvider, 'network', size, 'data_transfer', e.target.value)}
                  inputProps={{ step: 0.001 }}
                />
              </Grid>
              <Grid item xs={6}>
                <TextField
                  fullWidth
                  label="Bandwidth ($/GB)"
                  type="number"
                  value={costs.bandwidth}
                  onChange={(e) => handlePricingChange(selectedProvider, 'network', size, 'bandwidth', e.target.value)}
                  inputProps={{ step: 0.001 }}
                />
              </Grid>
            </Grid>
          </Grid>
        ))}
      </Grid>
    );
  };

  const renderConsumerPricing = () => {
    const consumerData = pricingData[selectedProvider].consumer;

    return (
      <Grid container spacing={2}>
        <Grid item xs={6}>
          <TextField
            fullWidth
            label="API Calls ($/call)"
            type="number"
            value={consumerData.api_calls}
            onChange={(e) => handlePricingChange(selectedProvider, 'consumer', null, 'api_calls', e.target.value)}
            inputProps={{ step: 0.0001 }}
          />
        </Grid>
        <Grid item xs={6}>
          <TextField
            fullWidth
            label="Data Distribution ($/GB)"
            type="number"
            value={consumerData.data_distribution}
            onChange={(e) => handlePricingChange(selectedProvider, 'consumer', null, 'data_distribution', e.target.value)}
            inputProps={{ step: 0.001 }}
          />
        </Grid>
      </Grid>
    );
  };

  const renderInfrastructurePricing = () => {
    const infraData = pricingData[selectedProvider].infrastructure;

    return (
      <Grid container spacing={2}>
        <Grid item xs={12}>
          <Typography variant="subtitle1" gutterBottom>
            Compute Resources
          </Typography>
          <Grid container spacing={2}>
            {Object.entries(infraData.compute).map(([size, cost]) => (
              <Grid item xs={4} key={size}>
                <TextField
                  fullWidth
                  label={`${size} ($/hour)`}
                  type="number"
                  value={cost}
                  onChange={(e) => handlePricingChange(selectedProvider, 'infrastructure', 'compute', size, e.target.value)}
                  inputProps={{ step: 0.001 }}
                />
              </Grid>
            ))}
          </Grid>
        </Grid>

        <Grid item xs={12}>
          <Typography variant="subtitle1" gutterBottom>
            Storage
          </Typography>
          <Grid container spacing={2}>
            {Object.entries(infraData.storage).map(([type, cost]) => (
              <Grid item xs={6} key={type}>
                <TextField
                  fullWidth
                  label={`${type} ($/GB/month)`}
                  type="number"
                  value={cost}
                  onChange={(e) => handlePricingChange(selectedProvider, 'infrastructure', 'storage', type, e.target.value)}
                  inputProps={{ step: 0.001 }}
                />
              </Grid>
            ))}
          </Grid>
        </Grid>

        <Grid item xs={12}>
          <Typography variant="subtitle1" gutterBottom>
            Services
          </Typography>
          <Grid container spacing={2}>
            {Object.entries(infraData.services).map(([service, cost]) => (
              <Grid item xs={6} key={service}>
                <TextField
                  fullWidth
                  label={`${service} ($/month)`}
                  type="number"
                  value={cost}
                  onChange={(e) => handlePricingChange(selectedProvider, 'infrastructure', 'services', service, e.target.value)}
                  inputProps={{ step: 0.01 }}
                />
              </Grid>
            ))}
          </Grid>
        </Grid>
      </Grid>
    );
  };

  const renderInfraParams = (category, params, title) => (
    <Accordion expanded={expanded === category} onChange={handleAccordionChange(category)}>
      <AccordionSummary expandIcon={<ExpandMoreIcon />}>
        <Typography variant="h6">{title}</Typography>
      </AccordionSummary>
      <AccordionDetails>
        <Grid container spacing={2}>
          {Object.entries(params).map(([param, value]) => (
            <Grid item xs={12} sm={6} md={4} key={param}>
              <TextField
                fullWidth
                label={param.split('_').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ')}
                type="number"
                value={value}
                onChange={handleInfraParamChange(category, param)}
                variant="outlined"
                size="small"
              />
            </Grid>
          ))}
        </Grid>
      </AccordionDetails>
    </Accordion>
  );

  return (
    <Container maxWidth="lg">
      <Paper elevation={3} sx={{ p: 3, mt: 3 }}>
        <Typography variant="h4" gutterBottom>
          Infrastructure Cost Configuration
        </Typography>

        <Accordion expanded={expanded === 'scale'} onChange={handleAccordionChange('scale')}>
          <AccordionSummary expandIcon={<ExpandMoreIcon />}>
            <Typography variant="h6">Scale Parameters</Typography>
          </AccordionSummary>
          <AccordionDetails>
            <Grid container spacing={2}>
              <Grid item xs={12} sm={4}>
                <TextField
                  fullWidth
                  label="Number of Tenants"
                  type="number"
                  value={scaleParams.num_tenants}
                  onChange={handleScaleParamChange('num_tenants')}
                />
              </Grid>
              <Grid item xs={12} sm={4}>
                <TextField
                  fullWidth
                  label="Consumers per Tenant"
                  type="number"
                  value={scaleParams.consumers_per_tenant}
                  onChange={handleScaleParamChange('consumers_per_tenant')}
                />
              </Grid>
              <Grid item xs={12} sm={4}>
                <TextField
                  fullWidth
                  label="Endpoints per Tenant"
                  type="number"
                  value={scaleParams.endpoints_per_tenant}
                  onChange={handleScaleParamChange('endpoints_per_tenant')}
                />
              </Grid>
            </Grid>
          </AccordionDetails>
        </Accordion>

        <Accordion expanded={expanded === 'load'} onChange={handleAccordionChange('load')}>
          <AccordionSummary expandIcon={<ExpandMoreIcon />}>
            <Typography variant="h6">Load Parameters</Typography>
          </AccordionSummary>
          <AccordionDetails>
            <Grid container spacing={2}>
              <Grid item xs={12}>
                <FormControlLabel
                  control={
                    <Switch
                      checked={loadParams.has_load}
                      onChange={handleLoadParamChange('has_load')}
                    />
                  }
                  label="Include Load Costs"
                />
              </Grid>
              <Grid item xs={12} sm={4}>
                <TextField
                  fullWidth
                  label="Messages per Day"
                  type="number"
                  value={loadParams.messages_per_day}
                  onChange={handleLoadParamChange('messages_per_day')}
                  disabled={!loadParams.has_load}
                />
              </Grid>
              <Grid item xs={12} sm={4}>
                <TextField
                  fullWidth
                  label="API Requests per Day"
                  type="number"
                  value={loadParams.api_requests_per_day}
                  onChange={handleLoadParamChange('api_requests_per_day')}
                  disabled={!loadParams.has_load}
                />
              </Grid>
              <Grid item xs={12} sm={4}>
                <TextField
                  fullWidth
                  label="Messages per Endpoint"
                  type="number"
                  value={loadParams.messages_per_endpoint}
                  onChange={handleLoadParamChange('messages_per_endpoint')}
                  disabled={!loadParams.has_load}
                />
              </Grid>
            </Grid>
          </AccordionDetails>
        </Accordion>

        {renderInfraParams('cloud_infra', infraParams.cloud_infra, 'AWS Cloud Infrastructure')}
        {renderInfraParams('infra_management', infraParams.infra_management, 'Infrastructure Management')}
        {renderInfraParams('security', infraParams.security, 'Security Tools')}
        {renderInfraParams('monitoring', infraParams.monitoring, 'Monitoring')}
        {renderInfraParams('load_balancing', infraParams.load_balancing, 'API & Load Balancing')}
        {renderInfraParams('caching', infraParams.caching, 'Caching')}
        {renderInfraParams('container', infraParams.container, 'Container Management')}

        <Box sx={{ mt: 3, display: 'flex', justifyContent: 'center' }}>
          <Button
            variant="contained"
            color="primary"
            onClick={calculateCosts}
            size="large"
          >
            Calculate Costs
          </Button>
        </Box>

        {costBreakdown && (
          <Box sx={{ mt: 3 }}>
            <Typography variant="h5" gutterBottom>Cost Breakdown</Typography>
            <Grid container spacing={2}>
              <Grid item xs={12} md={6}>
                <Paper elevation={2} sx={{ p: 2 }}>
                  <Typography variant="h6">Monthly Costs</Typography>
                  <Typography>Total: ${costBreakdown.total_monthly_cost.toFixed(2)}</Typography>
                  <Typography>Per Tenant: ${(costBreakdown.total_monthly_cost / scaleParams.num_tenants).toFixed(2)}</Typography>
                </Paper>
              </Grid>
              <Grid item xs={12} md={6}>
                <Paper elevation={2} sx={{ p: 2 }}>
                  <Typography variant="h6">Yearly Costs</Typography>
                  <Typography>Total: ${costBreakdown.total_yearly_cost.toFixed(2)}</Typography>
                  <Typography>Per Tenant: ${costBreakdown.cost_per_tenant.toFixed(2)}</Typography>
                </Paper>
              </Grid>
            </Grid>
          </Box>
        )}

        <Snackbar
          open={notification.open}
          autoHideDuration={6000}
          onClose={handleCloseNotification}
        >
          <Alert
            onClose={handleCloseNotification}
            severity={notification.severity}
            sx={{ width: '100%' }}
          >
            {notification.message}
          </Alert>
        </Snackbar>
      </Paper>
    </Container>
  );
}

export default PricingConfig;
